import { newSpecPage } from '@stencil/core/testing';
import { ScSubscription } from '../sc-subscription';

/**
 * A pause is `cancel_at_period_end` + `restore_at` — the same shape as a cancellation
 * without `restore_at`. The renewal copy lives in the nested sc-subscription-details;
 * what this component owns is the action button, which must not offer "Restore Plan"
 * for a plan that is only scheduled to pause. Passing `subscription` up front keeps
 * the component from fetching one.
 */
const renderActions = async (subscription: any) => {
  const page = await newSpecPage({
    components: [ScSubscription],
    html: `<sc-subscription></sc-subscription>`,
  });
  page.root.subscription = { can_modify: true, ...subscription };
  await page.waitForChanges();
  return page.root.shadowRoot.textContent;
};

const scheduledPause = {
  status: 'active',
  cancel_at_period_end: 1786000000,
  current_period_end_at: 1786000000,
  current_period_end_at_date: 'March 1, 2026',
  restore_at: 1817000000,
  restore_at_date: 'June 1, 2026',
};

describe('sc-subscription', () => {
  it("offers Don't Pause for a scheduled pause", async () => {
    const text = await renderActions(scheduledPause);
    expect(text).toContain("Don't Pause");
    expect(text).not.toContain('Restore Plan');
  });

  it('offers Restore Plan for a scheduled cancellation', async () => {
    const text = await renderActions({ ...scheduledPause, restore_at: null, restore_at_date: null });
    expect(text).toContain('Restore Plan');
    expect(text).not.toContain("Don't Pause");
  });
});
